def allocate(total, weights):
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError("total deve ser int")
    if not isinstance(weights, list):
        raise TypeError("weights deve ser uma lista")
    for weight in weights:
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError("cada peso deve ser int")

    if total < 0:
        raise ValueError("total deve ser não negativo")
    if not weights:
        raise ValueError("weights não pode ser vazia")
    if any(weight < 0 for weight in weights):
        raise ValueError("pesos devem ser não negativos")
    weight_sum = sum(weights)
    if weight_sum == 0:
        raise ValueError("deve haver pelo menos um peso positivo")

    allocated = []
    remainders = []
    for index, weight in enumerate(weights):
        quotient, remainder = divmod(total * weight, weight_sum)
        allocated.append(quotient)
        if remainder > 0:
            remainders.append((remainder, index))

    remaining = total - sum(allocated)
    remainders.sort(key=lambda item: (-item[0], item[1]))
    for position in range(remaining):
        allocated[remainders[position][1]] += 1

    return allocated
